NO_TASAR = {"15108", "15160", "15161"}   # Las Condes, Vitacura y Lo Barnechea (decisión del abogado)
consultas = 0


def llamar(servicio, cuerpo):
    global consultas
    time.sleep(0.7)
    consultas += 1
    req = urllib.request.Request(BASE + servicio, data=json.dumps(cuerpo).encode("utf-8"), method="POST",
                                 headers={"Content-Type": "application/json", "X-API-Key": KEY})
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            estado, texto = r.status, r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        estado, texto = e.code, e.read().decode("utf-8", "replace")
    except Exception as e:
        estado, texto = None, f"{type(e).__name__}"
    try:
        datos = json.loads(texto)
    except Exception:
        datos = {}
    res = datos.get("results") if isinstance(datos, dict) else None
    res = [x for x in res if isinstance(x, dict)] if isinstance(res, list) else []
    return estado, [{"rol": x.get("rol"), "address": x.get("address"), "useType": x.get("useType"),
                     "util": x.get("usefulSquareMeters"), "total": x.get("totalSquareMeters")} for x in res]


def norm_rol(r):
    m = re.match(r"\s*0*(\d+)\s*-\s*0*(\d+)", str(r or ""))
    return f"{m.group(1)}-{m.group(2)}" if m else str(r)


def elegir(res, numero):
    """Si hay varios resultados, el primero cuya dirección del SII trae el número del aviso."""
    for x in res:
        if re.search(rf"\b0*{int(numero)}\b", x.get("address") or ""):
            return x
    return res[0] if len(res) == 1 else None


def por_direccion(c):
    a = {"street": re.sub(r"(?i)^(calle|pasaje|avenida)\s+", "", c["calle"]).strip(), "streetNumber": str(int(c["numero"])),
         "comunaCode": c["comunaCode"]}
    b = {"street": c["calle"], "streetNumber": c["numero"], "comunaCode": c["comunaCode"]}
    if c["unitNumber"]:
        a["unitNumber"] = c["unitNumber"]
        b["unitNumber"] = c["unitNumber"].split("-")[0]
    for n, cuerpo in (("intento 1", a), ("intento 2", b)):
        estado, res = llamar("get_results_by_address", cuerpo)
        if estado == 200 and res:
            return n, len(res), elegir(res, c["numero"])
    return "no encontrada", 0, None


def tipo(x):
    if not x:
        return None
    d = (x.get("address") or "").upper()
    if (x.get("useType") or "").upper() != "HABITACIONAL":
        return "no habitacional"
    if re.search(r"\b(DP|DPTO|DEPTO)\b", d) or not x.get("total"):
        return "departamento"
    return "casa"


filas = []
for i, c in enumerate(CASOS, 1):
    f = {k: c[k] for k in ("causa", "comuna", "calle", "numero", "unidad", "rol_impreso")}
    elegido, via = None, None
    if c["rol_impreso"]:
        estado, res = llamar("get_results_by_rol", {"comunaCode": c["comunaCode"], "rol": c["rol_impreso"]})
        if estado == 200 and res:
            elegido, via = res[0], "por rol"
    n_dir, n_res, x_dir = por_direccion(c)
    f["direccion_resultado"] = n_dir
    f["direccion_n_resultados"] = n_res
    f["direccion_rol"] = norm_rol(x_dir["rol"]) if x_dir else None
    if c["rol_impreso"]:
        f["direccion_acierta_rol"] = (f["direccion_rol"] == norm_rol(c["rol_impreso"])) if x_dir else None
    if not elegido and x_dir:
        elegido, via = x_dir, f"por dirección ({n_dir})"
    f["via"] = via or "tasación no encontrada"
    f["sii"] = elegido
    f["tipo"] = tipo(elegido)
    if c["comunaCode"] in NO_TASAR:
        f["decision"] = "no se tasa (comuna)"
    elif not elegido:
        f["decision"] = "tasación no encontrada"
    elif f["tipo"] == "no habitacional":
        f["decision"] = "no habitacional, no se tasa"
    elif not elegido.get("util"):
        f["decision"] = "sin metros útiles"
    else:
        f["decision"] = "se tasaría (" + f["tipo"] + ")"
    filas.append(f)
    if i % 20 == 0:
        print(f"  {i} de {len(CASOS)} revisados ({consultas} consultas)")

def contar(clave):
    d = {}
    for f in filas:
        k = f[clave] if not str(f[clave]).startswith("se tasaría") else f[clave]
        d[k] = d.get(k, 0) + 1
    return d

lineas = [f"Inmuebles {len(filas)}. Consultas de búsqueda {consultas} (no se cobran).",
          "Decisión " + json.dumps(contar("decision"), ensure_ascii=False),
          "Vía " + json.dumps(contar("via"), ensure_ascii=False),
          "Búsqueda por dirección " + json.dumps(contar("direccion_resultado"), ensure_ascii=False)]
con_rol = [f for f in filas if f["rol_impreso"]]
lineas.append(f"Avisos con rol impreso {len(con_rol)}. La dirección da el mismo rol en "
              f"{sum(1 for f in con_rol if f.get('direccion_acierta_rol'))}, otro rol en "
              f"{sum(1 for f in con_rol if f.get('direccion_acierta_rol') is False)} y no encuentra en "
              f"{sum(1 for f in con_rol if f.get('direccion_acierta_rol') is None)}.")
(SALIDA / "cobertura.json").write_text(json.dumps(filas, ensure_ascii=False, indent=1), encoding="utf-8")
(SALIDA / "RESUMEN.txt").write_text("\n".join(lineas), encoding="utf-8")
print("\n" + "\n".join(lineas))
print(f"Listo. Archivos en {SALIDA}")
